    if alt is not None:
        attr_str += ' alt="%s"' % escape_text(alt)
    if width is not None:
        attr_str += ' width="%s"' % width
    if height is not None:
        attr_str += ' height="%s"' % height
    for key, value in attrs.items():
        if value is True:
            attr_str += ' %s' % key
        elif value is not None:
            attr_str += ' %s="%s"' % (key, escape_text(value))
    return '<img src="%s"%s />\n' % (escape_url(src), attr_str)
